<style>
:root{--ink:#172033;--muted:#64748b;--line:#e2e8f0;--bg:#f6f8fb;--primary:#6750a4;--good:#15803d;--warn:#a16207;--bad:#b91c1c}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"Segoe UI",sans-serif}.content{padding:30px 36px;max-width:1750px}.hero{background:linear-gradient(135deg,#7c2d12,#1e1b4b);color:#fff;border-radius:16px;padding:28px 32px;margin-bottom:20px}.hero h1{margin:0 0 7px;font-size:27px;display:flex;align-items:center;gap:10px}.hero p{margin:0;opacity:.9;font-size:14px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:18px;box-shadow:0 1px 3px #0000000d}.notice{padding:14px;border-radius:9px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-size:13px;margin-bottom:16px;line-height:1.5}.form-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr auto;gap:12px;align-items:end}.field label{display:block;font-size:12px;font-weight:800;color:#475569;margin-bottom:5px}.field input,.field select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:8px;padding:10px;background:#fff;font:inherit;font-size:13px}.btn,td button{border:1px solid #cbd5e1;background:#fff;border-radius:8px;padding:8px 11px;font:inherit;font-size:12px;font-weight:700;cursor:pointer}.btn-primary{border:0;background:var(--primary);color:#fff}.btn-danger{color:var(--bad)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:1450px}th,td{padding:10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:12px}th{background:#f8fafc;color:#475569;font-size:11px;text-transform:uppercase}.status{display:inline-flex;padding:4px 8px;border-radius:999px;background:#eef2f7;font-weight:800}.status.awaiting_approval,.status.rollback_awaiting_approval{background:#fffbeb;color:var(--warn)}.status.running,.status.backup_running,.status.approved,.status.rolling_back{background:#eff6ff;color:#1d4ed8}.status.completed,.status.rolled_back{background:#ecfdf3;color:var(--good)}.status.completed_with_errors{background:#fffbeb;color:var(--warn)}.status.failed,.status.cancelled{background:#fef2f2;color:var(--bad)}.small{font-size:11px;color:var(--muted)}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.logs{max-height:260px;overflow:auto;background:#0f172a;color:#dbeafe;border-radius:9px;padding:12px;font:12px Consolas,monospace;white-space:pre-wrap}.empty{padding:28px;text-align:center;color:var(--muted)}@media(max-width:1000px){.content{padding:20px}.form-grid{grid-template-columns:1fr}}
</style>
