<body>
<?php require_once '../includes/sidebar_nav.php'; ?>
<main class="content">
<section class="hero"><h1><i data-lucide="database-zap"></i> Full Database Restore</h1><p>Verified preview first, pre-restore backup second, then two-person approval before replacing the live database.</p></section>
<section class="card">
<div class="notice"><strong>Destructive operation:</strong> this feature replaces the live database with the verified SQL dump. It must be done during Maintenance Mode. The system requires a verified preview, a fresh rollback backup, two different administrator approvals, and an audit trail. PDF recovery is a separate controlled phase.</div>
<form id="form"><div class="form-grid"><div class="field"><label for="preview">Completed database restore preview</label><select id="preview" required><option value="">Loading...</option></select></div><div class="field"><label for="root">Rollback backup root</label><select id="root" required><option value="">Loading...</option></select></div><div class="field"><label for="folder">Rollback backup folder</label><input id="folder" maxlength="80" required value="iSCAN-PreRestore-DB-<?= date('Y-m-d-His') ?>"></div><button class="btn btn-primary" id="start" type="submit">Prepare restore</button></div></form>
<p class="small" id="maintenance">Maintenance Mode: checking...</p>
</section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Status</th><th>Preview</th><th>Pre-restore backup</th><th>Approvals</th><th>Tables</th><th>PDF findings</th><th>Created</th><th>Actions</th></tr></thead><tbody id="jobs"><tr><td colspan="9" class="empty">Loading...</td></tr></tbody></table></div><div class="pagination"><span class="small" id="summary">Loading...</span><span><button id="prev" disabled>Previous</button> <button id="next" disabled>Next</button></span></div></section>
<section class="card" id="detail" hidden><h2 style="margin-top:0" id="detail-title">Restore details</h2><p class="small" id="detail-summary"></p><div class="logs" id="logs"></div></section>
</main>
<script>
const api='../api/database_live_restore.php',csrf=document.querySelector('meta[name="csrf-token"]')?.content||'',preview=document.getElementById('preview'),root=document.getElementById('root'),jobs=document.getElementById('jobs'),summary=document.getElementById('summary');let page=1,maintenance=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));
async function request(url,options){const response=await fetch(url,{credentials:'same-origin',...(options||{})});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'Database restore request failed.');return data;}
async function loadSetup(){const data=await request(`${api}?action=locations`);maintenance=!!data.maintenance_mode;const m=document.getElementById('maintenance');m.textContent=`Maintenance Mode: ${maintenance?'ENABLED':'DISABLED — required before approval'}`;m.style.color=maintenance?'#15803d':'#b91c1c';root.innerHTML=(data.locations||[]).map(item=>`<option value="${esc(item.root)}">${esc(item.root)} — ${Number(item.free_gb||0).toLocaleString()} GB free — ${item.writable?'writable':'read-only'}</option>`).join('')||'<option value="">No approved roots available</option>';const eligible=await request(`${api}?action=eligible`);preview.innerHTML=(eligible.jobs||[]).map(item=>`<option value="${Number(item.id)}">Preview #${Number(item.id)} — ${Number(item.staging_table_count||0)} tables — ${Number(item.pdf_missing_count||0)} PDF missing</option>`).join('')||'<option value="">No eligible completed preview</option>';}
function approvalText(item){return`Restore ${Number(item.restore_stage1_count||0)}/1 + ${Number(item.restore_stage2_count||0)}/1<br>Rollback ${Number(item.rollback_stage1_count||0)}/1 + ${Number(item.rollback_stage2_count||0)}/1`}
function actions(item){let out=`<button data-detail="${Number(item.id)}">Details</button> <button data-sync="${Number(item.id)}">Sync</button>`;if(item.status==='awaiting_approval'){if(Number(item.restore_stage1_count||0)===0)out+=` <button data-approve="restore" data-stage="1" data-id="${Number(item.id)}">Restore Stage 1</button>`;else if(Number(item.restore_stage2_count||0)===0)out+=` <button data-approve="restore" data-stage="2" data-id="${Number(item.id)}">Restore Stage 2</button>`;}if(['completed','completed_with_errors','failed'].includes(item.status)){if(Number(item.rollback_stage1_count||0)===0)out+=` <button data-approve="rollback" data-stage="1" data-id="${Number(item.id)}">Rollback Stage 1</button>`;else if(Number(item.rollback_stage2_count||0)===0)out+=` <button data-approve="rollback" data-stage="2" data-id="${Number(item.id)}">Rollback Stage 2</button>`;}if(['backup_running','awaiting_approval','rollback_awaiting_approval'].includes(item.status))out+=` <button class="btn-danger" data-cancel="${Number(item.id)}">Cancel</button>`;return out;}
async function syncActive(items){const active=items.filter(item=>['backup_running','approved','running','rolling_back'].includes(item.status));if(active.length)await Promise.all(active.map(item=>post('sync',item.id).catch(()=>null)));}
async function loadJobs(){const data=await request(`${api}?action=list&page=${page}&per_page=25`),p=data.pagination;page=p.page;summary.textContent=p.total?`Showing ${p.from}-${p.to} of ${p.total} database restore gate(s)`:'No database restore gates yet';document.getElementById('prev').disabled=!p.has_previous;document.getElementById('next').disabled=!p.has_next;await syncActive(data.jobs||[]);if(!data.jobs.length){jobs.innerHTML='<tr><td colspan="9" class="empty">No database restore gates yet.</td></tr>';return;}jobs.innerHTML=data.jobs.map(item=>`<tr><td>#${Number(item.id)}</td><td><span class="status ${esc(item.status)}">${esc(item.status)}</span><div class="small">${esc(item.last_error||'')}</div></td><td>#${Number(item.preview_job_id)}<div class="small">${Number(item.preview_status?1:0)?esc(item.preview_status):''}</div></td><td>#${Number(item.pre_restore_backup_job_id||0)}<div class="small">${esc(item.pre_backup_status||'')}</div></td><td>${approvalText(item)}</td><td>${Number(item.target_table_count||0)} / ${Number(item.expected_table_count||0)}</td><td>${Number(item.pdf_missing_count||0)} missing · ${Number(item.pdf_invalid_count||0)} invalid</td><td>${esc(item.created_at||'')}</td><td>${actions(item)}</td></tr>`).join('');jobs.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>showDetail(Number(button.dataset.detail)).catch(error=>alert(error.message))));jobs.querySelectorAll('[data-sync]').forEach(button=>button.addEventListener('click',()=>post('sync',Number(button.dataset.sync)).then(loadJobs).catch(error=>alert(error.message))));jobs.querySelectorAll('[data-approve]').forEach(button=>button.addEventListener('click',()=>approve(Number(button.dataset.id),button.dataset.approve,Number(button.dataset.stage)).catch(error=>alert(error.message))));jobs.querySelectorAll('[data-cancel]').forEach(button=>button.addEventListener('click',()=>cancelJob(Number(button.dataset.cancel)).catch(error=>alert(error.message))));}
async function post(action,id,extra={}){const form=new FormData();form.append('action',action);if(id)form.append('job_id',id);form.append('csrf_token',csrf);Object.entries(extra).forEach(([key,value])=>form.append(key,value));return request(api,{method:'POST',body:form});}
async function showDetail(id){const data=await request(`${api}?action=job&job_id=${id}`);document.getElementById('detail').hidden=false;document.getElementById('detail-title').textContent=`Database restore gate #${id} — ${data.job.status}`;document.getElementById('detail-summary').textContent=`Preview #${data.job.preview_job_id} | pre-restore backup #${data.job.pre_restore_backup_job_id||'-'} | approvals: ${(data.approvals||[]).map(item=>`${item.action} Stage ${item.stage}: ${item.full_name||item.username||item.user_id}`).join(' · ')||'none'}`;document.getElementById('logs').textContent=(data.logs||[]).reverse().map(item=>`[${item.created_at}] ${String(item.level).toUpperCase()}: ${item.message}`).join('\n')||'No logs yet.';}
async function approve(id,operation,stage){if(!maintenance){alert('Enable Maintenance Mode first.');return;}const label=operation==='rollback'?'rollback':'full database restore';if(!confirm(`Record ${label} approval Stage ${stage} for gate #${id}? This may lead to a live database replacement.`))return;await post('approve',id,{operation,stage});await loadJobs();alert(`Approval Stage ${stage} recorded.`);}
async function cancelJob(id){if(!confirm(`Cancel database restore gate #${id}? Existing backups remain available.`))return;await post('cancel',id);await loadJobs();}
document.getElementById('form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('start');button.disabled=true;const form=new FormData();form.append('action','create');form.append('preview_job_id',preview.value);form.append('storage_root',root.value);form.append('folder_name',document.getElementById('folder').value);form.append('csrf_token',csrf);try{const data=await request(api,{method:'POST',body:form});alert(`${data.message} Gate ID: ${data.job_id}`);await loadJobs();}catch(error){alert(error.message);}finally{button.disabled=false;}});document.getElementById('prev').addEventListener('click',()=>{if(page>1){page--;loadJobs().catch(error=>alert(error.message));}});document.getElementById('next').addEventListener('click',()=>{page++;loadJobs().catch(error=>alert(error.message));});if(window.lucide)lucide.createIcons();Promise.all([loadSetup(),loadJobs()]).catch(error=>alert(error.message));setInterval(()=>loadSetup().then(loadJobs).catch(()=>{}),5000);
</script>
</body>
</html>
